253:                     <MenuItem value="selected">{t('deviceSelected')}</MenuItem>
254:                     <MenuItem value="all">{t('notificationAlways')}</MenuItem>
255:                   </Select>
256:                 </FormControl>
257:                 <FormGroup>
258:                   <FormControlLabel
259:                     control={
260:                       <Checkbox
261:                         checked={
262:                           attributes.hasOwnProperty('mapFollow') ? attributes.mapFollow : false
263:                         }
264:                         onChange={(e) =>
265:                           setAttributes({ ...attributes, mapFollow: e.target.checked })
266:                         }
267:                       />
268:                     }
269:                     label={t('deviceFollow')}
270:                   />
271:                   <FormControlLabel
272:                     control={
273:                       <Checkbox
274:                         checked={
275:                           attributes.hasOwnProperty('mapCluster') ? attributes.mapCluster : true
276:                         }
277:                         onChange={(e) =>
278:                           setAttributes({ ...attributes, mapCluster: e.target.checked })
279:                         }
280:                       />
281:                     }
282:                     label={t('mapClustering')}
283:                   />
284:                   <FormControlLabel
285:                     control={
286:                       <Checkbox
287:                         checked={
288:                           attributes.hasOwnProperty('mapOnSelect') ? attributes.mapOnSelect : true
289:                         }
290:                         onChange={(e) =>
291:                           setAttributes({ ...attributes, mapOnSelect: e.target.checked })
292:                         }
293:                       />
294:                     }
295:                     label={t('mapOnSelect')}
296:                   />
297:                 </FormGroup>
298:               </AccordionDetails>
299:             </Accordion>
300:             <Accordion>
301:               <AccordionSummary expandIcon={<ExpandMoreIcon />}>
302:                 <Typography variant="subtitle1">{t('deviceTitle')}</Typography>
303:               </AccordionSummary>
304:               <AccordionDetails className={classes.details}>
305:                 <SelectField
306:                   value={attributes.devicePrimary || 'name'}
307:                   onChange={(e) => setAttributes({ ...attributes, devicePrimary: e.target.value })}
308:                   data={deviceFields}
309:                   titleGetter={(it) => t(it.name)}
310:                   label={t('devicePrimaryInfo')}
311:                 />
312:                 <SelectField
313:                   value={attributes.deviceSecondary}
314:                   onChange={(e) =>
315:                     setAttributes({ ...attributes, deviceSecondary: e.target.value })
316:                   }
317:                   data={deviceFields}
318:                   titleGetter={(it) => t(it.name)}
319:                   label={t('deviceSecondaryInfo')}
320:                 />
321:               </AccordionDetails>
322:             </Accordion>
323:             <Accordion>
324:               <AccordionSummary expandIcon={<ExpandMoreIcon />}>
325:                 <Typography variant="subtitle1">{t('sharedSound')}</Typography>
326:               </AccordionSummary>
327:               <AccordionDetails className={classes.details}>
328:                 <SelectField
329:                   multiple
330:                   value={attributes.soundEvents?.split(',') || []}
331:                   onChange={(e) =>
332:                     setAttributes({ ...attributes, soundEvents: e.target.value.join(',') })
333:                   }
334:                   endpoint="/api/notifications/types"
335:                   keyGetter={(it) => it.type}
336:                   titleGetter={(it) => t(prefixString('event', it.type))}
337:                   label={t('eventsSoundEvents')}
338:                 />
339:                 <SelectField
340:                   multiple
341:                   value={attributes.soundAlarms?.split(',') || ['sos']}
342:                   onChange={(e) =>
343:                     setAttributes({ ...attributes, soundAlarms: e.target.value.join(',') })
344:                   }
345:                   data={alarms}
346:                   keyGetter={(it) => it.key}
347:                   label={t('eventsSoundAlarms')}
348:                 />
349:               </AccordionDetails>
350:             </Accordion>
351:           </>
352:         )}
353:         <Accordion>
354:           <AccordionSummary expandIcon={<ExpandMoreIcon />}>
355:             <Typography variant="subtitle1">{t('userToken')}</Typography>
356:           </AccordionSummary>
357:           <AccordionDetails className={classes.details}>
358:             <TextField
359:               label={t('userExpirationTime')}
360:               type="date"
361:               value={tokenExpiration}
362:               onChange={(e) => {
363:                 setTokenExpiration(e.target.value);
364:                 setToken(null);
365:               }}
366:             />
367:             <FormControl>
368:               <OutlinedInput
369:                 multiline
370:                 rows={6}
371:                 readOnly
372:                 type="text"
373:                 value={token || ''}
374:                 endAdornment={
375:                   <InputAdornment position="end">
376:                     <div className={classes.verticalActions}>
377:                       <IconButton
378:                         size="small"
379:                         edge="end"
380:                         onClick={generateToken}
381:                         disabled={!!token}
382:                       >
383:                         <CachedIcon fontSize="small" />
384:                       </IconButton>
385:                       <IconButton
386:                         size="small"
387:                         edge="end"
388:                         onClick={() => navigator.clipboard.writeText(token)}
389:                         disabled={!token}
390:                       >
391:                         <ContentCopyIcon fontSize="small" />
392:                       </IconButton>
393:                     </div>
394:                   </InputAdornment>
395:                 }
396:               />
397:             </FormControl>
398:           </AccordionDetails>
399:         </Accordion>
400:         {!readonly && (
401:           <>
402:             <Accordion>
403:               <AccordionSummary expandIcon={<ExpandMoreIcon />}>
404:                 <Typography variant="subtitle1">{t('sharedInfoTitle')}</Typography>
405:               </AccordionSummary>
406:               <AccordionDetails className={classes.details}>
407:                 <TextField value={versionApp} label={t('settingsAppVersion')} disabled />
408:                 <TextField
409:                   value={versionServer || '-'}
410:                   label={t('settingsServerVersion')}
411:                   disabled
412:                 />
413:                 <TextField
414:                   value={socket ? t('deviceStatusOnline') : t('deviceStatusOffline')}
415:                   label={t('settingsConnection')}
416:                   disabled
417:                 />
418:                 <Button variant="outlined" color="primary" onClick={() => navigate('/emulator')}>
419:                   {t('sharedEmulator')}
420:                 </Button>
421:                 {admin && (
422:                   <Button variant="outlined" color="error" onClick={handleReboot}>
423:                     {t('serverReboot')}
424:                   </Button>
425:                 )}
426:               </AccordionDetails>
427:             </Accordion>
428:             <div className={classes.buttons}>
429:               <Button type="button" color="primary" variant="outlined" onClick={() => navigate(-1)}>
430:                 {t('sharedCancel')}
431:               </Button>
432:               <Button type="button" color="primary" variant="contained" onClick={handleSave}>
433:                 {t('sharedSave')}
434:               </Button>
435:             </div>
436:           </>
437:         )}
438:       </Container>
439:     </PageLayout>
440:   );
441: };
442: 
443: export default PreferencesPage;
